 LinearLayout panel; void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->action.run());panel.addView(b);} void info(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(17);t.setPadding(8,16,8,16);panel.addView(t);} void open(String action){try{startActivity(new Intent(action));}catch(Exception e){toast("Settings unavailable");}} void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 public void onCreate(Bundle savedInstanceState){super.onCreate(savedInstanceState);if(Intent.ACTION_VIEW.equals(getIntent().getAction())){String p=getIntent().getStringExtra("package");String c=getIntent().getStringExtra("class");if(p!=null&&c!=null){try{Intent launch=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setPackage(p);boolean allowed=false;for(ResolveInfo ri:getPackageManager().queryIntentActivities(launch,0)){if(ri.activityInfo!=null&&p.equals(ri.activityInfo.packageName)&&c.equals(ri.activityInfo.name)&&ri.activityInfo.exported){allowed=true;break;}}if(!allowed)throw new SecurityException("Not a public launcher activity");startActivity(launch.setComponent(new ComponentName(p,c)));finish();return;}catch(Exception e){toast("App unavailable");}}}ScrollView scroll=new ScrollView(this);panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(24,40,24,24);panel.setBackgroundColor(0xff102331);scroll.addView(panel);setContentView(scroll);info("CG Pixel Guardian 7.0 — Google Trust\nSecurity & home screen recovery");info(Build.MODEL+" · Android "+Build.VERSION.RELEASE+"\nSecurity patch: "+Build.VERSION.SECURITY_PATCH);BatteryManager bm=getSystemService(BatteryManager.class);info("Battery: "+bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)+"%\nAvailable storage: "+new StatFs(getFilesDir().getPath()).getAvailableBytes()/1073741824L+" GB");button("Enroll trusted Foresiva signer",()->new AlertDialog.Builder(this).setTitle("Trust installed Foresiva?").setMessage("Only enroll after independently verifying this installation. Re-enrollment replaces the previous baseline.").setPositiveButton("Enroll",(d,w)->{try{String h=GuardianAudit.baseline(this);GuardianAudit.record(this,"Foresiva signer enrolled");showReport("Trusted baseline",h);}catch(Exception e){toast("Foresiva signer unavailable");}}).setNegativeButton("Cancel",null).show());button("Audit Foresiva now",()->new Thread(()->showReport("Foresiva audit",GuardianAudit.audit(this))).start());if(!GuardianAudit.prefs(this).getBoolean("automation_disabled",false)){scheduleDefense();}button("Enable automatic audits and alerts",()->{GuardianAudit.prefs(this).edit().putBoolean("automation_disabled",false).apply();if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},33);scheduleDefense();toast("Hourly audit requested; Android may delay execution");});button("Disable scheduled audits",()->{GuardianAudit.prefs(this).edit().putBoolean("automation_disabled",true).apply();androidx.work.WorkManager.getInstance(this).cancelUniqueWork("guardian-initial");androidx.work.WorkManager.getInstance(this).cancelUniqueWork("guardian-daily");toast("Cancellation requested");});button("Sixth Sense status",()->{long last=GuardianAudit.prefs(this).getLong("last_audit",0);showReport("Guardian heartbeat",last==0?"No completed audit yet":"Last audit: "+new java.util.Date(last)+(System.currentTimeMillis()-last>21600000L?"\nAudit overdue; check Android background settings":"\nAudit within six hours"));});button("CG Friction Defense — simulation",()->new AlertDialog.Builder(this).setTitle("Friction Defense test").setMessage("Simulate an unexpected interaction with a fictional resource. This is a local test, not malware detection.").setPositiveButton("Run simulation",(d,w)->{GuardianAudit.record(this,"SIMULATION ONLY: synthetic decoy interaction; no real threat detected");showReport("Friction Defense","Synthetic incident recorded in security history. No applications, financial records or network settings changed.");}).setNegativeButton("Cancel",null).show());button("CG Fraud Shield — inspect link",()->inspectFraudLink());button("Scam call protection guide",()->showReport("Pixel scam call protection","Open Phone > three dots > Settings > Caller ID & spam. Enable caller ID and spam protection. Use Call Screen if available. Never share verification codes; hang up and call the organization using a trusted number. Guardian does not intercept calls."));button("Report suspected phishing to Google",()->openFraudPage("https://safebrowsing.google.com/safebrowsing/report_phish/"));button("Report fraud to FTC",()->openFraudPage("https://reportfraud.ftc.gov/"));button("CG FutureTrace — security checkpoint",()->new AlertDialog.Builder(this).setTitle("FutureTrace").setMessage("Compare visible application versions, granted permissions and security patch against a checkpoint you choose. A checkpoint is not proof of safety.").setPositiveButton("Compare",(d,w)->futureTrace(false)).setNeutralButton("Save checkpoint",(d,w)->new AlertDialog.Builder(this).setTitle("Replace checkpoint?").setMessage("This replaces only the FutureTrace comparison baseline.").setPositiveButton("Save",(a,b)->futureTrace(true)).setNegativeButton("Cancel",null).show()).setNegativeButton("Cancel",null).show());button("Security Receipts — 30 days",()->sentinelReceipts(null));button("FirstRun Shield — review new apps",()->firstRunReview());button("Panic Freeze — emergency controls",()->new AlertDialog.Builder(this).setTitle("Emergency controls").setMessage("Guardian cannot freeze other apps or cut network access itself. Use Android controls to disconnect Wi-Fi and mobile data, then review suspicious apps.").setPositiveButton("Network settings",(d,w)->open("android.settings.WIRELESS_SETTINGS")).setNeutralButton("Review apps",(d,w)->open(Settings.ACTION_APPLICATION_SETTINGS)).setNegativeButton("Close",null).show());button("Exposure Guard — check link or filename",()->exposureReview());button("Incident Replay — compare checkpoint",()->futureTrace(false));button("Security history",()->showReport("Security history",GuardianAudit.prefs(this).getString("history","No audit history")));button("Scan APK file",()->pickApk());button("Audit installed apps",()->auditApps());button("Find apps and create shortcuts",()->apps());button("Default home app",()->open(Settings.ACTION_HOME_SETTINGS));button("Installed apps",()->open(Settings.ACTION_APPLICATION_SETTINGS));button("Security settings",()->open(Settings.ACTION_SECURITY_SETTINGS));button("Google Play Protect",()->{try{Intent i=new Intent("com.google.android.finsky.PLAY_PROTECT");i.setPackage("com.android.vending");startActivity(i);}catch(Exception e){openGooglePlay();}});button("Google Play Store",()->openGooglePlay());button("Google Play system updates",()->{try{startActivity(new Intent("android.settings.MODULE_UPDATE_SETTINGS"));}catch(Exception e){open(Settings.ACTION_SECURITY_SETTINGS);}});button("Pixel app permissions",()->open(Settings.ACTION_APPLICATION_SETTINGS));button("Pixel device security",()->open(Settings.ACTION_SECURITY_SETTINGS));button("Privacy settings",()->open(Settings.ACTION_PRIVACY_SETTINGS));button("System updates / device information",()->{try{startActivity(new Intent("android.settings.SYSTEM_UPDATE_SETTINGS"));}catch(Exception e){open(Settings.ACTION_DEVICE_INFO_SETTINGS);}});button("Storage settings",()->open(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));button("Battery settings",()->open(Settings.ACTION_BATTERY_SAVER_SETTINGS));info("For malware scanning, open Google Play Store > profile > Play Protect > Scan. Guardian performs local APK and permission analysis, not comprehensive malware detection. No threat database is installed.");}
 void openFraudPage(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)));}catch(Exception e){toast("Browser unavailable");}}
 void inspectFraudLink(){EditText input=new EditText(this);input.setSingleLine(true);input.setHint("Paste full website URL");new AlertDialog.Builder(this).setTitle("Local link inspection").setView(input).setPositiveButton("Inspect",(d,w)->{try{java.net.URI u=new java.net.URI(input.getText().toString().trim());String host=u.getHost();if(host==null||u.getScheme()==null||!u.getScheme().matches("(?i)https?")){showReport("Link review","Invalid or unsupported web address. Do not open.");return;}StringBuilder flags=new StringBuilder();if(!"https".equalsIgnoreCase(u.getScheme()))flags.append("Unencrypted HTTP.\n");if(u.getRawUserInfo()!=null)flags.append("Embedded user information can disguise destination.\n");if(host.toLowerCase(java.util.Locale.ROOT).contains("xn--"))flags.append("Internationalized domain: verify spelling.\n");if(host.matches("[0-9.]+")||host.contains(":"))flags.append("Numeric host: verify destination.\n");showReport("Link review","Destination: "+host+"\n"+(flags.length()==0?"No basic warning signs found.":flags.toString())+"\nNot a reputation check or safety verdict. Verify independently and use Chrome Safe Browsing. Link was not opened or uploaded.");}catch(Exception e){showReport("Link review","Invalid URL. Do not open.");}}).setNegativeButton("Cancel",null).show();}
 void futureTrace(boolean save){new Thread(()->{try{org.json.JSONObject now=new org.json.JSONObject();now.put("Security patch",Build.VERSION.SECURITY_PATCH);for(PackageInfo p:getPackageManager().getInstalledPackages(PackageManager.GET_PERMISSIONS)){java.util.TreeSet<String> granted=new java.util.TreeSet<>();if(p.requestedPermissions!=null&&p.requestedPermissionsFlags!=null)for(int i=0;i<Math.min(p.requestedPermissions.length,p.requestedPermissionsFlags.length);i++)if((p.requestedPermissionsFlags[i]&PackageInfo.REQUESTED_PERMISSION_GRANTED)!=0)granted.add(p.requestedPermissions[i]);now.put("App: "+p.packageName,String.valueOf(p.versionName)+" | "+(Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode)+" | "+granted);}android.content.SharedPreferences prefs=getSharedPreferences("futuretrace",MODE_PRIVATE);if(save){boolean ok=prefs.edit().putString("baseline",now.toString()).putLong("time",System.currentTimeMillis()).commit();showReport("FutureTrace",ok?"Checkpoint saved locally. Not a malware safety verdict.":"Checkpoint could not be saved.");return;}String raw=prefs.getString("baseline",null);if(raw==null){showReport("FutureTrace","Save a checkpoint first.");return;}org.json.JSONObject old=new org.json.JSONObject(raw);StringBuilder report=new StringBuilder("Checkpoint: "+new java.util.Date(prefs.getLong("time",0))+"\n");java.util.TreeSet<String> keys=new java.util.TreeSet<>();old.keys().forEachRemaining(keys::add);now.keys().forEachRemaining(keys::add);int count=0;for(String key:keys){if(!old.optString(key).equals(now.optString(key))){count++;if(count<=50)report.append("\n").append(key).append("\nBefore: ").append(old.optString(key,"Not visible")).append("\nNow: ").append(now.optString(key,"Not visible")).append("\n");}}showReport("FutureTrace comparison",count+" changes\n"+report+"\nOnly visible apps are compared. Changes may be normal; no changes does not mean safe. First 50 changes shown.");}catch(Exception e){showReport("FutureTrace","Comparison incomplete.");}}).start();}
 synchronized void sentinelReceipts(String finding){try{android.content.SharedPreferences p=getSharedPreferences("sentinel_receipts",MODE_PRIVATE);org.json.JSONArray old=new org.json.JSONArray(p.getString("entries","[]"));org.json.JSONArray fresh=new org.json.JSONArray();long now=System.currentTimeMillis();for(int i=0;i<old.length();i++){org.json.JSONObject e=old.optJSONObject(i);if(e!=null&&e.optLong("time")>=now-2592000000L&&fresh.length()<199)fresh.put(e);}if(finding!=null){org.json.JSONObject e=new org.json.JSONObject();e.put("time",now);e.put("reason",finding);fresh.put(e);}p.edit().putString("entries",fresh.toString()).apply();if(finding==null){StringBuilder b=new StringBuilder("Review receipts only. No automatic blocking or quarantine. No changes to undo.\n");for(int i=fresh.length()-1;i>=0;i--){org.json.JSONObject e=fresh.getJSONObject(i);b.append(new java.util.Date(e.optLong("time"))).append(": ").append(e.optString("reason")).append("\n");}showReport("Security Receipts",b.toString());}}catch(Exception e){showReport("Security Receipts","Receipt processing incomplete.");}}
 void firstRunReview(){new Thread(()->{try{android.content.SharedPreferences p=getSharedPreferences("sentinel_first_run",MODE_PRIVATE);java.util.Set<String> prior=new java.util.HashSet<>(p.getStringSet("seen",java.util.Collections.emptySet()));java.util.Set<String> current=new java.util.HashSet<>();StringBuilder b=new StringBuilder();boolean initial=!p.contains("seen");int count=0;for(PackageInfo app:getPackageManager().getInstalledPackages(0)){current.add(app.packageName);if(!initial&&!prior.contains(app.packageName)){count++;if(count<=50)b.append(app.packageName).append("\n");}}prior.addAll(current);p.edit().putStringSet("seen",prior).apply();String msg=initial?"Initial visible-app baseline saved. Not proof of safety.":count+" newly observed apps. Visibility changes may be normal.\n"+b;sentinelReceipts(initial?"FirstRun baseline created.":count+" newly observed visible apps; review permissions in Android settings.");showReport("FirstRun Shield",msg+"\nNo apps were restricted. Use Installed apps to review permissions before use.");}catch(Exception e){showReport("FirstRun Shield","Review incomplete.");}}).start();}
 void exposureReview(){EditText input=new EditText(this);input.setHint("Paste a link or filename");input.setSingleLine(true);new AlertDialog.Builder(this).setTitle("Exposure Guard").setView(input).setPositiveButton("Review",(d,w)->{String v=input.getText().toString().trim();String lower=v.toLowerCase(java.util.Locale.ROOT);String reason;if(lower.startsWith("http://")||lower.startsWith("https://")){try{java.net.URI u=new java.net.URI(v);String h=u.getHost();reason=h==null?"Invalid or ambiguous URL.":(!"https".equalsIgnoreCase(u.getScheme())||u.getRawUserInfo()!=null||h.toLowerCase(java.util.Locale.ROOT).contains("xn--")||h.matches("[0-9.]+")||h.contains(":"))?"URL has warning signs; verify destination independently.":"No basic URL warning signs found.";}catch(Exception e){reason="Invalid URL.";}}else{reason=lower.matches(".*[.](pdf|jpg|png|docx|txt|zip)[.](apk|exe|js|bat|scr|cmd)$")?"Double extension may disguise executable content.":lower.endsWith(".apk")?"Android installer: verify source and signer before installing.":"No basic filename warning signs found.";}sentinelReceipts(reason);showReport("Exposure Guard",reason+"\nNo reputation lookup or file-content scan performed. Nothing opened or uploaded.");}).setNegativeButton("Cancel",null).show();}
 void apps(){Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> list=getPackageManager().queryIntentActivities(q,0);list.sort(new ResolveInfo.DisplayNameComparator(getPackageManager()));String[] names=new String[list.size()];for(int i=0;i<names.length;i++)names[i]=list.get(i).loadLabel(getPackageManager()).toString();new AlertDialog.Builder(this).setTitle("Choose a launchable app").setItems(names,(d,i)->pin(list.get(i),names[i])).show();}
 void pin(ResolveInfo r,String name){try{ShortcutManager m=getSystemService(ShortcutManager.class);if(!m.isRequestPinShortcutSupported()){toast("Launcher does not support shortcuts");return;}Intent launch=new Intent(this,MainActivity.class).setAction(Intent.ACTION_VIEW).putExtra("package",r.activityInfo.packageName).putExtra("class",r.activityInfo.name);ShortcutInfo s=new ShortcutInfo.Builder(this,"app-"+r.activityInfo.packageName+"-"+r.activityInfo.name).setShortLabel(name).setIntent(launch).build();toast(m.requestPinShortcut(s,null)?"Confirm shortcut on your home screen":"Shortcut request declined");}catch(Exception e){toast("Shortcut unavailable for this app");}}

 void pickApk(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");try{startActivityForResult(i,41);}catch(Exception e){toast("File picker unavailable");}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req!=41||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri uri=data.getData();toast("Analyzing locally…");new Thread(()->{java.io.File f=null;try{f=java.io.File.createTempFile("guardian-", ".apk",getCacheDir());java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");long total=0;try(java.io.InputStream in=getContentResolver().openInputStream(uri);java.io.OutputStream out=new java.io.FileOutputStream(f)){if(in==null)throw new java.io.IOException("Cannot read file");byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1){total+=n;if(total>536870912L)throw new java.io.IOException("File exceeds 512 MB scan limit");digest.update(buf,0,n);out.write(buf,0,n);}}PackageInfo p=getPackageManager().getPackageArchiveInfo(f.getAbsolutePath(),flags());String report="SHA-256: "+hex(digest.digest())+"\nBytes: "+total+"\n\n"+(p==null?"APK could not be parsed. No safety verdict.":describe(p))+"\n\nNo malware signature database configured. Unknown threat status; absence of flags does not mean safe.";showReport("APK analysis",report);}catch(Exception e){showReport("Scan incomplete",String.valueOf(e.getMessage()));}finally{if(f!=null)f.delete();}}).start();}
 int flags(){return PackageManager.GET_PERMISSIONS|(Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES);}
 String hex(byte[] bytes){StringBuilder b=new StringBuilder();for(byte v:bytes)b.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return b.toString();}
 String describe(PackageInfo p){StringBuilder b=new StringBuilder("Package: "+p.packageName+"\nVersion: "+p.versionName+"\n");try{android.content.pm.Signature[] sig=Build.VERSION.SDK_INT>=28?(p.signingInfo==null?null:p.signingInfo.getApkContentsSigners()):p.signatures;if(sig==null||sig.length==0)b.append("Signer unavailable\n");else for(android.content.pm.Signature x:sig)b.append("Signer SHA-256: ").append(hex(java.security.MessageDigest.getInstance("SHA-256").digest(x.toByteArray()))).append("\n");}catch(Exception e){b.append("Signer inspection failed\n");}b.append("Requested permissions:\n");if(p.requestedPermissions!=null)for(String perm:p.requestedPermissions){boolean flag=perm.matches("android\\.permission\\.(READ_SMS|SEND_SMS|RECEIVE_SMS|READ_CONTACTS|RECORD_AUDIO|CAMERA|ACCESS_FINE_LOCATION|REQUEST_INSTALL_PACKAGES|SYSTEM_ALERT_WINDOW|MANAGE_EXTERNAL_STORAGE|READ_CALL_LOG|QUERY_ALL_PACKAGES)");b.append(flag?"Review: ":"").append(perm).append("\n");}b.append("Permission flags are contextual, not proof of malware. Certificate fingerprints do not establish trust.");return b.toString();}
 void showReport(String title,String report){runOnUiThread(()->{if(isFinishing()||isDestroyed())return;new AlertDialog.Builder(this).setTitle(title).setMessage(report).setPositiveButton("Close",null).setNeutralButton("Copy report",(d,w)->{android.content.ClipboardManager c=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);c.setPrimaryClip(ClipData.newPlainText("Guardian report",report));}).show();});}
 void auditApps(){new Thread(()->{try{List<PackageInfo> list=getPackageManager().getInstalledPackages(flags());StringBuilder b=new StringBuilder("Visible packages: "+list.size()+" (Android limits visibility)\n\n");for(PackageInfo p:list)b.append(describe(p)).append("\n\n");showReport("Installed app audit",b.toString());}catch(Exception e){showReport("Audit incomplete",String.valueOf(e.getMessage()));}}).start();}
 void scheduleDefense(){androidx.work.WorkManager wm=androidx.work.WorkManager.getInstance(this);wm.enqueueUniquePeriodicWork("guardian-daily",androidx.work.ExistingPeriodicWorkPolicy.UPDATE,new androidx.work.PeriodicWorkRequest.Builder(GuardianAudit.class,1,java.util.concurrent.TimeUnit.HOURS).build());if(GuardianAudit.prefs(this).getLong("last_audit",0)==0)wm.enqueueUniqueWork("guardian-initial",androidx.work.ExistingWorkPolicy.KEEP,new androidx.work.OneTimeWorkRequest.Builder(GuardianAudit.class).build());}
